mapper.select:
SELECT MAX(lr.report_time) AS reportTime, MAX(lr.patient_id) AS patientId, MAX(lr.execute_dept) AS executeDept, MAX(lr.execute_doc) AS executeDoc, MAX(lr.report_url) AS reportUrl, COUNT(*) AS itemCount, SUM(CASE WHEN lr.item_id IS NOT NULL AND lr.item_id > 0 AND EXISTS ( SELECT 1 FROM lab_item_dict d WHERE d.item_id = lr.item_id AND d.normal_range IS NOT NULL AND d.normal_range != '' AND ( lr.result_value < CAST(SUBSTRING_INDEX(d.normal_range, '-', 1) AS DECIMAL(10,2)) OR lr.result_value > CAST(SUBSTRING_INDEX(d.normal_range, '-', -1) AS DECIMAL(10,2)) ) ) THEN 1 ELSE 0 END) AS abnormalCount FROM lab_result lr
lr.is_invalid = 0
AND lr.patient_id LIKE CONCAT('%', #{patientId}, '%')
AND EXISTS ( SELECT 1 FROM patient p WHERE p.patient_id = lr.patient_id AND p.patient_name LIKE CONCAT('%', #{patientName}, '%') )
AND EXISTS ( SELECT 1 FROM lab_item_dict d WHERE d.item_id = lr.item_id AND d.item_name LIKE CONCAT('%', #{testName}, '%') )
AND lr.result_value LIKE CONCAT('%', #{resultValue}, '%')
AND lr.execute_doc LIKE CONCAT('%', #{executeDoc}, '%')
AND lr.execute_dept = #{executeDept}
AND lr.report_time BETWEEN #{startTime} AND #{endTime}
AND lr.report_time < #{cursor}
GROUP BY lr.report_time ORDER BY lr.report_time DESC LIMIT #{pageSize}
